echo "== responses and requests in spool order (line: compact)"
jq -c --argjson n 0 'select(.type=="response" or .type=="request") | {type, id, method, result: (.result|tostring|.[0:160]), error, params: (.params|tostring|.[0:400])}' $SP | nl -ba | head -0
awk '{print NR": "$0}' $SP | while IFS= read -r l; do :; done
python3 - <<'PY'
import json
sp='/Users/dct/.droid-observatory/hosted/386a27bd-035c-4ffd-a981-dd2026e2349c.jsonl'
off=0
for i,raw in enumerate(open(sp,'rb'),1):
    o=json.loads(raw)
    t=o.get('type'); n=(o.get('params') or {}).get('notification') or {}
    k=n.get('type')
    show=None
    if t in('response','request'):
        show={'type':t,'id':o.get('id'),'method':o.get('method'),'result':json.dumps(o.get('result'))[:200] if 'result' in o else None,'error':o.get('error'),'params':json.dumps(o.get('params'))[:500] if t=='request' else None}
    elif k in ('queued_messages_discarded','permission_resolved','agent_turn_completed'):
        show={'notification':k,'body':json.dumps(n)[:400]}
    elif k=='create_message':
        m=n.get('message',{})
        parts=[]
        for p in m.get('content',[]) or []:
            if p.get('type')=='text': parts.append('text:'+p.get('text','')[:80].replace('\n',' '))
            elif p.get('type')=='tool_use': parts.append(f"tool_use:{p.get('name')}:{p.get('id')}")
            elif p.get('type')=='tool_result': parts.append(f"tool_result:{p.get('tool_use_id')}")
        show={'create_message':m.get('role'),'parts':parts}
    if show: print(f"L{i} off={off}", json.dumps(show, ensure_ascii=False))
    off+=len(raw)
PY
